(* Aggregate audit of live theorem objects against separately frozen registries.
   Parsing a stored target is not acceptance: it must equal a reconstructed theorem. *)
List.iter (fun r -> r := None)
 [printer_color_const; printer_color_resword; printer_color_binder;
  printer_color_infix; printer_color_prefix; printer_color_type;
  printer_color_typevar; printer_color_itypevar];;
let assurance_aggregate_audit path =
 let items = [
  "ASSURANCE_OBSERVED_PROJECTION",parse_term "!s obs s'. assurance_observed_step s obs s' ==> x86 s s'",ASSURANCE_OBSERVED_PROJECTION;
  "ASSURANCE_OBSERVED_BACKLIFT_ALL",parse_term "!s s'. x86 s s' ==> ?obs. assurance_observed_step s obs s'",ASSURANCE_OBSERVED_BACKLIFT_ALL;
  "ASSURANCE_OBSERVED_EQUIVALENCE",parse_term "!s s'. (?obs. assurance_observed_step s obs s') <=> x86 s s'",ASSURANCE_OBSERVED_EQUIVALENCE;
  "ASSURANCE_OBSERVED_PROGRESS",parse_term "!s. (?s'. x86 s s') <=> ?obs s'. assurance_observed_step s obs s'",ASSURANCE_OBSERVED_PROGRESS;
  "ASSURANCE_OBSERVED_FETCH_CORRESPONDENCE",parse_term "!s ip len inst es s'.\n    assurance_observed_step s (ip,len,inst,es) s'\n    ==> ip = read RIP s /\\\n        x86_decode s ip (len,inst) /\\\n        (?l. bytes_loaded s ip l /\\ LENGTH l = len /\\\n             decode l = SOME(inst,[]))",ASSURANCE_OBSERVED_FETCH_CORRESPONDENCE;
  "ASSURANCE_DELTA_EXACT",parse_term "!s s' d. read events s' = APPEND d (read events s)\n             ==> assurance_delta s s' = d",ASSURANCE_DELTA_EXACT;
  "ASSURANCE_OBSERVATION_EVENT_ORDER",parse_term "!s s' len inst d.\n    read events s' = APPEND d (read events s)\n    ==> assurance_observation s len inst s' =\n        (read RIP s,len,inst,REVERSE d)",ASSURANCE_OBSERVATION_EVENT_ORDER;
  "ASSURANCE_DELTA_CONCATENATION",parse_term "!s0 s1 s2 d1 d2.\n    read events s1 = APPEND d1 (read events s0) /\\\n    read events s2 = APPEND d2 (read events s1)\n    ==> assurance_delta s0 s2 = APPEND d2 d1 /\\\n        REVERSE(assurance_delta s0 s2) =\n          APPEND (REVERSE d1) (REVERSE d2)",ASSURANCE_DELTA_CONCATENATION;
  "ASSURANCE_EVENTUALLY_CORRESPONDENCE",parse_term "!P s. eventually (\\a b. ?obs. assurance_observed_step a obs b) P s\n           <=> eventually x86 P s",ASSURANCE_EVENTUALLY_CORRESPONDENCE;
  "ASSURANCE_EXECUTE_RET",parse_term "x86_execute RET = x86_RET",ASSURANCE_EXECUTE_RET;
  "ASSURANCE_ACTUAL_RET_PROJECTION",parse_term "!len s s'. assurance_actual_ret len s s' ==> x86 s s'",ASSURANCE_ACTUAL_RET_PROJECTION;
  "ASSURANCE_ACTUAL_RET_EFFECTS",parse_term "!len s s'. assurance_actual_ret len s s'\n    ==> read RSP s' = word_add (read RSP s) (word 8) /\\\n        read RIP s' = read (memory :> bytes64 (read RSP s)) s /\\\n        read events s' = APPEND\n          [EventJump(word_add (read RIP s) (word len),\n                     read (memory :> bytes64 (read RSP s)) s);\n           EventLoad(read RSP s,8)] (read events s)",ASSURANCE_ACTUAL_RET_EFFECTS;
  "ASSURANCE_ACTUAL_RET_OBSERVATION",parse_term "!len s s'. assurance_actual_ret len s s'\n    ==> assurance_observation s len RET s' =\n        (read RIP s,len,RET,\n         [EventLoad(read RSP s,8);\n          EventJump(word_add (read RIP s) (word len),\n                    read (memory :> bytes64 (read RSP s)) s)])",ASSURANCE_ACTUAL_RET_OBSERVATION;
  "ASSURANCE_DECODED_RET_ALL_SUCCESSORS",parse_term "!len s. x86_decode s (read RIP s) (len,RET)\n    ==> !s'. x86 s s' ==> assurance_actual_ret len s s'",ASSURANCE_DECODED_RET_ALL_SUCCESSORS;
  "ASSURANCE_DECODED_RET_PROGRESS",parse_term "!len s. x86_decode s (read RIP s) (len,RET)\n    ==> ?s'. assurance_actual_ret len s s'",ASSURANCE_DECODED_RET_PROGRESS;
  "ASSURANCE_SPAN_SUBRANGE",parse_term "!perm a width offset count.\n    assurance_span_ok perm a width /\\ offset+count <= width\n    ==> assurance_span_ok perm (a+offset) count",ASSURANCE_SPAN_SUBRANGE;
  "ASSURANCE_ZERO_STACK_EVENT_POLICY",parse_term "!rp wp ip ra sp.\n    assurance_span_ok rp (val(sp:int64)) 8\n    ==> ALL (assurance_event_policy rp wp)\n        [EventJump(ip,ra);EventLoad(sp,8)]",ASSURANCE_ZERO_STACK_EVENT_POLICY;
  "ASSURANCE_RET_EVENT_POLICY",parse_term "!rp wp len s s'.\n    assurance_actual_ret len s s' /\\\n    assurance_span_ok rp (val(read RSP s)) 8\n    ==> ALL (assurance_event_policy rp wp)\n              (assurance_delta s s')",ASSURANCE_RET_EVENT_POLICY;
  "ASSURANCE_STACK_ADVANCE_NONWRAP",parse_term "!stackpointer:int64. val stackpointer + 8 < 2 EXP 64\n    ==> val(word_add stackpointer (word 8)) = val stackpointer + 8",ASSURANCE_STACK_ADVANCE_NONWRAP;
  "ASSURANCE_FETCH_INTERVAL_FROM_REGION",parse_term "!xp codebase codesize ip len inst es.\n    assurance_span_ok xp (val(codebase:int64)) codesize /\\\n    val codebase <= val(ip:int64) /\\\n    val ip+len <= val codebase+codesize\n    ==> assurance_fetch_policy xp (ip,len,inst,es)",ASSURANCE_FETCH_INTERVAL_FROM_REGION;
  "ASSURANCE_SPAN_SELF_REGION",parse_term "!rp p n. assurance_span_ok rp (val(p:int64)) n\n    ==> assurance_span_ok\n          (\\a. rp a /\\ assurance_region p n a) (val p) n",ASSURANCE_SPAN_SELF_REGION;
  "ASSURANCE_SPAN_MONO",parse_term "!rp rp' a width.\n    assurance_span_ok rp a width /\\ (!x. rp x ==> rp' x)\n    ==> assurance_span_ok rp' a width",ASSURANCE_SPAN_MONO;
  "ASSURANCE_SPAN_WORD_OFFSET_8",parse_term "!rp p. assurance_span_ok rp (val(p:int64)) 16\n    ==> assurance_span_ok rp (val(word_add p (word 8))) 8",ASSURANCE_SPAN_WORD_OFFSET_8;
  "ASSURANCE_SPAN_PREFIX",parse_term "!rp a width count.\n    assurance_span_ok rp a width /\\ count <= width\n    ==> assurance_span_ok rp a count",ASSURANCE_SPAN_PREFIX;
  "ASSURANCE_CRYPTO_16_DATA_POLICY",parse_term "!rp wp p q stackpointer ip ra.\n    assurance_span_ok rp (val(p:int64)) 16 /\\\n    assurance_span_ok rp (val(q:int64)) 16 /\\\n    assurance_span_ok rp (val(stackpointer:int64)) 8\n    ==> ALL (assurance_event_policy\n          (\\a. rp a /\\ (assurance_region p 16 a \\/\n                        assurance_region q 16 a \\/\n                        assurance_region stackpointer 8 a)) wp)\n        [EventJump(ip,ra);EventLoad(stackpointer,8);\n         EventLoad(word_add q (word 8),8);EventLoad(q,8);\n         EventLoad(word_add p (word 8),8);EventLoad(p,8)]",ASSURANCE_CRYPTO_16_DATA_POLICY;
  "ASSURANCE_CRYPTO_ZERO_REACHES_RET_READY",parse_term "!pc sp ra p q e.\n    ensures x86\n      (\\s. bytes_loaded s (word pc) crypto_memcmp_mc /\\\n           read RIP s = word pc /\\ read RSP s = sp /\\\n           read (memory :> bytes64 sp) s = ra /\\\n           C_ARGUMENTS [p;q;word 0] s /\\ read events s = e)\n      (\\s. read RIP s = word(pc+93) /\\ read RSP s = sp /\\\n           read RAX s = word 0 /\\\n           bytes_loaded s (word pc) crypto_memcmp_mc /\\\n           read (memory :> bytes64 sp) s = ra /\\\n           x86_decode s (read RIP s) (2,RET) /\\\n           read events s = APPEND\n             [EventJump(word(pc+16),word(pc+93))] e)\n      (MAYCHANGE [RIP;RAX;R10] ,, MAYCHANGE SOME_FLAGS ,,\n       MAYCHANGE [events])",ASSURANCE_CRYPTO_ZERO_REACHES_RET_READY;
  "ASSURANCE_CRYPTO_16_REACHES_RET_READY",parse_term "!pc sp ra p q a0 a1 b0 b1 e.\n    ensures x86\n      (\\s. bytes_loaded s (word pc) crypto_memcmp_mc /\\\n           read RIP s = word pc /\\ read RSP s = sp /\\\n           read (memory :> bytes64 sp) s = ra /\\\n           C_ARGUMENTS [p;q;word 16] s /\\\n           read (memory :> bytes64 p) s = a0 /\\\n           read (memory :> bytes64 (word_add p (word 8))) s = a1 /\\\n           read (memory :> bytes64 q) s = b0 /\\\n           read (memory :> bytes64 (word_add q (word 8))) s = b1 /\\\n           read events s = e)\n      (\\s. read RIP s = word(pc+50) /\\ read RSP s = sp /\\\n           read RAX s = (if a0 = b0 /\\ a1 = b1 then word 0 else word 1) /\\\n           bytes_loaded s (word pc) crypto_memcmp_mc /\\\n           read (memory :> bytes64 sp) s = ra /\\\n           x86_decode s (read RIP s) (2,RET) /\\\n           read events s = APPEND\n             [EventLoad(word_add q (word 8),8);EventLoad(q,8);\n              EventLoad(word_add p (word 8),8);EventLoad(p,8);\n              EventJump(word(pc+22),word(pc+22));\n              EventJump(word(pc+16),word(pc+16))] e)\n      (MAYCHANGE [RIP;RAX;RDX;R10;R11] ,, MAYCHANGE SOME_FLAGS ,,\n       MAYCHANGE [events])",ASSURANCE_CRYPTO_16_REACHES_RET_READY;
  "ASSURANCE_RUN_PROJECT",parse_term "!n P C s. assurance_checked_run n P C s\n    ==> eventually_n x86 n P s",ASSURANCE_RUN_PROJECT;
  "ASSURANCE_RUN_EVENTUALLY",parse_term "!n P C s. assurance_checked_run n P C s ==> eventually x86 P s",ASSURANCE_RUN_EVENTUALLY;
  "ASSURANCE_RUN_ALL_SUCCESSORS",parse_term "!n P C s. assurance_checked_run (SUC n) P C s\n    ==> (?s'. x86 s s') /\\\n        !s'. x86 s s' ==> C (SUC n) s s' /\\\n                           assurance_checked_run n P C s'",ASSURANCE_RUN_ALL_SUCCESSORS;
  "ASSURANCE_DECODED_OBSERVATION_ALL_SUCCESSORS",parse_term "!len inst s s'.\n    x86_decode s (read RIP s) (len,inst) /\\ x86 s s'\n    ==> assurance_observed_step s\n          (assurance_observation s len inst s') s'",ASSURANCE_DECODED_OBSERVATION_ALL_SUCCESSORS;
  "ASSURANCE_ALL_REVERSE",parse_term "!P (l:A list). ALL P (REVERSE l) <=> ALL P l",ASSURANCE_ALL_REVERSE;
  "ASSURANCE_STEP_POLICY_OBSERVED",parse_term "!rp wp xp s s'.\n    x86 s s' /\\ assurance_step_policy rp wp xp s s'\n    ==> ?obs. assurance_observed_step s obs s' /\\\n              assurance_fetch_policy xp obs /\\\n              ALL (assurance_event_policy rp wp) (SND(SND(SND obs))) /\\\n              read events s' = APPEND (REVERSE(SND(SND(SND obs))))\n                                      (read events s)",ASSURANCE_STEP_POLICY_OBSERVED;
  "ASSURANCE_CODE_OFFSET_VALUE",parse_term "!pc offset. pc+95 <= 2 EXP 64 /\\ offset < 95\n    ==> val(word(pc+offset):int64) = pc+offset",ASSURANCE_CODE_OFFSET_VALUE;
  "ASSURANCE_CODE_BASE_VALUE",parse_term "!pc. pc+95 <= 2 EXP 64 ==> val(word pc:int64) = pc",ASSURANCE_CODE_BASE_VALUE;
  "ASSURANCE_RUN_STEP",parse_term "!n P C s. assurance_checked_run (1+n) P C s <=>\n     (?s'. x86 s s') /\\\n     !s'. x86 s s' ==> C (1+n) s s' /\\\n                        assurance_checked_run n P C s'",ASSURANCE_RUN_STEP;
  "ASSURANCE_RET_FROM_DECODE_AND_STEP",parse_term "!len s s'. x86_decode s (read RIP s) (len,RET) /\\ x86 s s'\n    ==> assurance_actual_ret len s s'",ASSURANCE_RET_FROM_DECODE_AND_STEP;
  "ASSURANCE_CRYPTO_ZERO_COMPLETE_POLICY",parse_term "!pc stackpointer ra p q xp rp e s.\n    pc+95 <= 2 EXP 64 /\\ assurance_span_ok xp pc 95 /\\\n    assurance_span_ok\n      (\\a. rp a /\\ assurance_region stackpointer 8 a)\n      (val(stackpointer:int64)) 8 /\\\n    bytes_loaded s (word pc) crypto_memcmp_mc /\\\n    read RIP s = word pc /\\ read RSP s = stackpointer /\\\n    read (memory :> bytes64 stackpointer) s = ra /\\\n    C_ARGUMENTS [p;q;word 0] s /\\ read events s = e\n    ==> assurance_checked_run 6\n      (\\s'. read RIP s' = ra /\\\n            read RSP s' = word_add stackpointer (word 8) /\\\n            read RAX s' = word 0 /\\\n            bytes_loaded s' (word pc) crypto_memcmp_mc /\\\n            read events s' = APPEND\n              [EventJump(word(pc+95),ra);EventLoad(stackpointer,8);\n               EventJump(word(pc+16),word(pc+93))] e)\n      (assurance_zero_step\n        (\\a. rp a /\\ assurance_region stackpointer 8 a) (\\a. F) xp) s",ASSURANCE_CRYPTO_ZERO_COMPLETE_POLICY;
  "ABI_SCALAR_EXTENDED_PROJECTION",parse_term "!s a s' a'. abi_scalar_extended_step (s,a) (s',a') ==> x86 s s'",ABI_SCALAR_EXTENDED_PROJECTION;
  "ABI_SCALAR_EXTENDED_BACKLIFT_ALL",parse_term "!s s' a. x86 s s' ==> abi_scalar_extended_step (s,a) (s',a)",ABI_SCALAR_EXTENDED_BACKLIFT_ALL;
  "ABI_SCALAR_EXTENDED_EQUIVALENCE",parse_term "!s s' a. (?a'. abi_scalar_extended_step (s,a) (s',a')) <=> x86 s s'",ABI_SCALAR_EXTENDED_EQUIVALENCE;
  "ABI_SCALAR_EXTENDED_PROGRESS",parse_term "!s a. (?s'. x86 s s') <=> ?s' a'. abi_scalar_extended_step (s,a) (s',a')",ABI_SCALAR_EXTENDED_PROGRESS;
  "ABI_SCALAR_STEP_PRESERVES_OMITTED",parse_term "!s a s' a'. abi_scalar_extended_step (s,a) (s',a') /\\\n                abi_all_decodes_scalar s ==> a' = a",ABI_SCALAR_STEP_PRESERVES_OMITTED;
  "ABI_SCALAR_EQUAL_IMPLIES_REQUIRED_CONTROLS",parse_term "!a a'. a' = a ==> abi_required_controls_preserved a a'",ABI_SCALAR_EQUAL_IMPLIES_REQUIRED_CONTROLS;
  "ABI_CRYPTO_REGISTERED_SITE_IS_SCALAR",parse_term "!off len inst. abi_crypto_site off len inst ==> abi_scalar_instruction inst",ABI_CRYPTO_REGISTERED_SITE_IS_SCALAR;
  "ABI_CHECKED_RUN_LIFT",parse_term "!n P C s a.\n    assurance_checked_run n P\n      (\\k source target. C k source target /\\ abi_all_decodes_scalar source) s\n    ==> eventually_n abi_scalar_extended_step n\n          (\\t. P(FST t) /\\ SND t = a) (s,a)",ABI_CHECKED_RUN_LIFT;
  "ASSURANCE_DECODED_SCALAR_UNIQUE",parse_term "!len inst s. x86_decode s (read RIP s) (len,inst) /\\\n                abi_scalar_instruction inst\n    ==> abi_all_decodes_scalar s",ASSURANCE_DECODED_SCALAR_UNIQUE;
  "ASSURANCE_CRYPTO_ZERO_SCALAR_QUALIFIED_POLICY",parse_term "!pc stackpointer ra p q xp rp e s.\n    pc+95 <= 2 EXP 64 /\\ assurance_span_ok xp pc 95 /\\\n    assurance_span_ok\n      (\\a. rp a /\\ assurance_region stackpointer 8 a)\n      (val(stackpointer:int64)) 8 /\\\n    bytes_loaded s (word pc) crypto_memcmp_mc /\\\n    read RIP s = word pc /\\ read RSP s = stackpointer /\\\n    read (memory :> bytes64 stackpointer) s = ra /\\\n    C_ARGUMENTS [p;q;word 0] s /\\ read events s = e\n    ==> assurance_checked_run 6\n      (\\s'. read RIP s' = ra /\\\n            read RSP s' = word_add stackpointer (word 8) /\\\n            read RAX s' = word 0 /\\\n            bytes_loaded s' (word pc) crypto_memcmp_mc /\\\n            read events s' = APPEND\n              [EventJump(word(pc+95),ra);EventLoad(stackpointer,8);\n               EventJump(word(pc+16),word(pc+93))] e)\n      (assurance_zero_scalar_step\n        (\\a. rp a /\\ assurance_region stackpointer 8 a) (\\a. F) xp) s",ASSURANCE_CRYPTO_ZERO_SCALAR_QUALIFIED_POLICY;
  "ASSURANCE_CRYPTO_16_STRICT_SPANS",parse_term "!rp p q stackpointer.\n    assurance_span_ok rp (val(p:int64)) 16 /\\\n    assurance_span_ok rp (val(q:int64)) 16 /\\\n    assurance_span_ok rp (val(stackpointer:int64)) 8\n    ==> assurance_span_ok\n         (\\a. rp a /\\ (assurance_region p 16 a \\/ assurance_region q 16 a \\/\n                       assurance_region stackpointer 8 a)) (val p) 8 /\\\n        assurance_span_ok\n         (\\a. rp a /\\ (assurance_region p 16 a \\/ assurance_region q 16 a \\/\n                       assurance_region stackpointer 8 a))\n         (val(word_add p (word 8))) 8 /\\\n        assurance_span_ok\n         (\\a. rp a /\\ (assurance_region p 16 a \\/ assurance_region q 16 a \\/\n                       assurance_region stackpointer 8 a)) (val q) 8 /\\\n        assurance_span_ok\n         (\\a. rp a /\\ (assurance_region p 16 a \\/ assurance_region q 16 a \\/\n                       assurance_region stackpointer 8 a))\n         (val(word_add q (word 8))) 8 /\\\n        assurance_span_ok\n         (\\a. rp a /\\ (assurance_region p 16 a \\/ assurance_region q 16 a \\/\n                       assurance_region stackpointer 8 a)) (val stackpointer) 8",ASSURANCE_CRYPTO_16_STRICT_SPANS;
  "ASSURANCE_CRYPTO_16_COMPLETE_POLICY",parse_term "!pc stackpointer ra p q xp rp a0 a1 b0 b1 e s.\n    pc+95 <= 2 EXP 64 /\\ assurance_span_ok xp pc 95 /\\\n    assurance_span_ok rp (val(p:int64)) 16 /\\\n    assurance_span_ok rp (val(q:int64)) 16 /\\\n    assurance_span_ok rp (val(stackpointer:int64)) 8 /\\\n    bytes_loaded s (word pc) crypto_memcmp_mc /\\\n    read RIP s = word pc /\\ read RSP s = stackpointer /\\\n    read (memory :> bytes64 stackpointer) s = ra /\\\n    C_ARGUMENTS [p;q;word 16] s /\\\n    read (memory :> bytes64 p) s = a0 /\\\n    read (memory :> bytes64 (word_add p (word 8))) s = a1 /\\\n    read (memory :> bytes64 q) s = b0 /\\\n    read (memory :> bytes64 (word_add q (word 8))) s = b1 /\\\n    read events s = e\n    ==> assurance_checked_run 15\n      (\\s'. read RIP s' = ra /\\\n            read RSP s' = word_add stackpointer (word 8) /\\\n            read RAX s' = (if a0 = b0 /\\ a1 = b1 then word 0 else word 1) /\\\n            bytes_loaded s' (word pc) crypto_memcmp_mc /\\\n            read events s' = APPEND\n              [EventJump(word(pc+52),ra);EventLoad(stackpointer,8);\n               EventLoad(word_add q (word 8),8);EventLoad(q,8);\n               EventLoad(word_add p (word 8),8);EventLoad(p,8);\n               EventJump(word(pc+22),word(pc+22));\n               EventJump(word(pc+16),word(pc+16))] e)\n      (assurance_zero_step\n        (\\a. rp a /\\ (assurance_region p 16 a \\/ assurance_region q 16 a \\/\n                      assurance_region stackpointer 8 a)) (\\a. F) xp) s",ASSURANCE_CRYPTO_16_COMPLETE_POLICY;
  "ASSURANCE_CRYPTO_16_SCALAR_QUALIFIED_POLICY",parse_term "!pc stackpointer ra p q xp rp a0 a1 b0 b1 e s.\n    pc+95 <= 2 EXP 64 /\\ assurance_span_ok xp pc 95 /\\\n    assurance_span_ok rp (val(p:int64)) 16 /\\\n    assurance_span_ok rp (val(q:int64)) 16 /\\\n    assurance_span_ok rp (val(stackpointer:int64)) 8 /\\\n    bytes_loaded s (word pc) crypto_memcmp_mc /\\\n    read RIP s = word pc /\\ read RSP s = stackpointer /\\\n    read (memory :> bytes64 stackpointer) s = ra /\\\n    C_ARGUMENTS [p;q;word 16] s /\\\n    read (memory :> bytes64 p) s = a0 /\\\n    read (memory :> bytes64 (word_add p (word 8))) s = a1 /\\\n    read (memory :> bytes64 q) s = b0 /\\\n    read (memory :> bytes64 (word_add q (word 8))) s = b1 /\\\n    read events s = e\n    ==> assurance_checked_run 15\n      (\\s'. read RIP s' = ra /\\\n            read RSP s' = word_add stackpointer (word 8) /\\\n            read RAX s' = (if a0 = b0 /\\ a1 = b1 then word 0 else word 1) /\\\n            bytes_loaded s' (word pc) crypto_memcmp_mc /\\\n            read events s' = APPEND\n              [EventJump(word(pc+52),ra);EventLoad(stackpointer,8);\n               EventLoad(word_add q (word 8),8);EventLoad(q,8);\n               EventLoad(word_add p (word 8),8);EventLoad(p,8);\n               EventJump(word(pc+22),word(pc+22));\n               EventJump(word(pc+16),word(pc+16))] e)\n      (assurance_zero_scalar_step\n        (\\a. rp a /\\ (assurance_region p 16 a \\/ assurance_region q 16 a \\/\n                      assurance_region stackpointer 8 a)) (\\a. F) xp) s",ASSURANCE_CRYPTO_16_SCALAR_QUALIFIED_POLICY;
  "ASSURANCE_SCALAR_POLICY_RUN_LIFT",parse_term "!n P rp wp xp s a.\n    assurance_checked_run n P (assurance_zero_scalar_step rp wp xp) s\n    ==> eventually_n abi_scalar_extended_step n\n          (\\t. P(FST t) /\\ SND t = a) (s,a)",ASSURANCE_SCALAR_POLICY_RUN_LIFT;
  "ASSURANCE_SCALAR_POLICY_RUN_CONTROLS",parse_term "!n P rp wp xp s a.\n    assurance_checked_run n P (assurance_zero_scalar_step rp wp xp) s\n    ==> eventually_n abi_scalar_extended_step n\n          (\\t. P(FST t) /\\ abi_required_controls_preserved a (SND t)) (s,a)",ASSURANCE_SCALAR_POLICY_RUN_CONTROLS;
  "ASSURANCE_E2_PERMISSION_FUNCTIONS",parse_term "(!xp ordinary pc. bp_e2_crypto_allowed_fetch xp ordinary pc =\n     (\\a. (xp a /\\ ordinary a) /\\ assurance_region (word pc) 95 a)) /\\\n   (!rp ordinary p q n stackpointer.\n      bp_e2_crypto_allowed_read rp ordinary p q n stackpointer =\n      (\\a. (rp a /\\ ordinary a) /\\\n        (assurance_region p n a \\/ assurance_region q n a \\/\n         assurance_region stackpointer 8 a))) /\\\n   bp_e2_crypto_allowed_write = (\\a:num. F)",ASSURANCE_E2_PERMISSION_FUNCTIONS;
  "ASSURANCE_E2_FETCH_SPAN",parse_term "!pc stackpointer ra p q n m rp xp ordinary s.\n    bp_e2_crypto_pre pc stackpointer ra p q n m rp xp ordinary s\n    ==> assurance_span_ok (bp_e2_crypto_allowed_fetch xp ordinary pc) pc 95",ASSURANCE_E2_FETCH_SPAN;
  "ASSURANCE_E2_READ_SPANS",parse_term "!rp ordinary p q n stackpointer.\n    assurance_span_ok (\\a. rp a /\\ ordinary a) (val(p:int64)) n /\\\n    assurance_span_ok (\\a. rp a /\\ ordinary a) (val(q:int64)) n /\\\n    assurance_span_ok (\\a. rp a /\\ ordinary a) (val(stackpointer:int64)) 8\n    ==> assurance_span_ok\n          (bp_e2_crypto_allowed_read rp ordinary p q n stackpointer) (val p) n /\\\n        assurance_span_ok\n          (bp_e2_crypto_allowed_read rp ordinary p q n stackpointer) (val q) n /\\\n        assurance_span_ok\n          (bp_e2_crypto_allowed_read rp ordinary p q n stackpointer)\n          (val stackpointer) 8",ASSURANCE_E2_READ_SPANS;
  "ASSURANCE_E2_ZERO_ALLOWED_READ",parse_term "!rp ordinary p q stackpointer.\n    bp_e2_crypto_allowed_read rp ordinary p q 0 stackpointer =\n      (\\a. (rp a /\\ ordinary a) /\\ assurance_region stackpointer 8 a)",ASSURANCE_E2_ZERO_ALLOWED_READ;
  "ASSURANCE_E2_POLICY_PRODUCT",parse_term "!n P rp wp xp s a.\n    assurance_checked_run n P (assurance_zero_scalar_step rp wp xp) s\n    ==> eventually_n abi_scalar_extended_step n\n          (\\t. P(FST t) /\\ SND t = a /\\\n               abi_required_controls_preserved a (SND t)) (s,a)",ASSURANCE_E2_POLICY_PRODUCT;
  "ASSURANCE_E2_CHECKED_RUN_MONO",parse_term "!n P Q C s. (!t. P t ==> Q t) /\\ assurance_checked_run n P C s\n    ==> assurance_checked_run n Q C s",ASSURANCE_E2_CHECKED_RUN_MONO;
  "ASSURANCE_CRYPTO_ZERO_FRAMED_POLICY",parse_term "!pc stackpointer ra p q xp rp e m s.\n    pc+95 <= 2 EXP 64 /\\ assurance_span_ok xp pc 95 /\\\n    assurance_span_ok\n      (\\a. rp a /\\ assurance_region stackpointer 8 a)\n      (val(stackpointer:int64)) 8 /\\\n    bytes_loaded s (word pc) crypto_memcmp_mc /\\\n    read RIP s = word pc /\\ read RSP s = stackpointer /\\\n    read (memory :> bytes64 stackpointer) s = ra /\\\n    C_ARGUMENTS [p;q;word 0] s /\\ read events s = e /\\ read memory s = m\n    ==> assurance_checked_run 6\n      (\\s'. read RIP s' = ra /\\\n            read RSP s' = word_add stackpointer (word 8) /\\\n            read RAX s' = word 0 /\\\n            bytes_loaded s' (word pc) crypto_memcmp_mc /\\\n            read events s' = APPEND\n              [EventJump(word(pc+95),ra);EventLoad(stackpointer,8);\n               EventJump(word(pc+16),word(pc+93))] e /\\ read memory s' = m /\\\n            (MAYCHANGE [RIP;RSP;RAX;RDI;RSI;RDX;R10;R11] ,,\n             MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events]) s s')\n      (assurance_zero_scalar_step\n        (\\a. rp a /\\ assurance_region stackpointer 8 a) (\\a. F) xp) s",ASSURANCE_CRYPTO_ZERO_FRAMED_POLICY;
  "ASSURANCE_CRYPTO_16_FRAMED_POLICY",parse_term "!pc stackpointer ra p q xp rp a0 a1 b0 b1 e m s.\n    pc+95 <= 2 EXP 64 /\\ assurance_span_ok xp pc 95 /\\\n    assurance_span_ok rp (val(p:int64)) 16 /\\\n    assurance_span_ok rp (val(q:int64)) 16 /\\\n    assurance_span_ok rp (val(stackpointer:int64)) 8 /\\\n    bytes_loaded s (word pc) crypto_memcmp_mc /\\\n    read RIP s = word pc /\\ read RSP s = stackpointer /\\\n    read (memory :> bytes64 stackpointer) s = ra /\\\n    C_ARGUMENTS [p;q;word 16] s /\\\n    read (memory :> bytes64 p) s = a0 /\\\n    read (memory :> bytes64 (word_add p (word 8))) s = a1 /\\\n    read (memory :> bytes64 q) s = b0 /\\\n    read (memory :> bytes64 (word_add q (word 8))) s = b1 /\\\n    read events s = e /\\ read memory s = m\n    ==> assurance_checked_run 15\n      (\\s'. read RIP s' = ra /\\\n            read RSP s' = word_add stackpointer (word 8) /\\\n            read RAX s' = (if a0 = b0 /\\ a1 = b1 then word 0 else word 1) /\\\n            bytes_loaded s' (word pc) crypto_memcmp_mc /\\\n            read events s' = APPEND\n              [EventJump(word(pc+52),ra);EventLoad(stackpointer,8);\n               EventLoad(word_add q (word 8),8);EventLoad(q,8);\n               EventLoad(word_add p (word 8),8);EventLoad(p,8);\n               EventJump(word(pc+22),word(pc+22));\n               EventJump(word(pc+16),word(pc+16))] e /\\ read memory s' = m /\\\n            (MAYCHANGE [RIP;RSP;RAX;RDI;RSI;RDX;R10;R11] ,,\n             MAYCHANGE SOME_FLAGS ,, MAYCHANGE [events]) s s')\n      (assurance_zero_scalar_step\n        (\\a. rp a /\\ (assurance_region p 16 a \\/ assurance_region q 16 a \\/\n                      assurance_region stackpointer 8 a)) (\\a. F) xp) s",ASSURANCE_CRYPTO_16_FRAMED_POLICY;
  "ASSURANCE_E2_ZERO_POLICY_FRAME",parse_term "!pc stackpointer ra p q m rp xp ordinary s.\n    bp_e2_crypto_pre pc stackpointer ra p q 0 m rp xp ordinary s\n    ==> assurance_checked_run 6\n      (bp_assurance_zero_post pc stackpointer ra (read events s) m s)\n      (assurance_zero_scalar_step\n        (bp_e2_crypto_allowed_read rp ordinary p q 0 stackpointer)\n        bp_e2_crypto_allowed_write (bp_e2_crypto_allowed_fetch xp ordinary pc)) s",ASSURANCE_E2_ZERO_POLICY_FRAME;
