  "ASSURANCE_E2_16_BYTE_POLICY_FRAME",parse_term "!pc stackpointer ra p q m rp xp ordinary s.\n    bp_e2_crypto_pre pc stackpointer ra p q 16 m rp xp ordinary s\n    ==> assurance_checked_run 15\n      (bp_assurance_16_byte_post pc stackpointer ra p q (read events s) m s)\n      (assurance_zero_scalar_step\n        (bp_e2_crypto_allowed_read rp ordinary p q 16 stackpointer)\n        bp_e2_crypto_allowed_write (bp_e2_crypto_allowed_fetch xp ordinary pc)) s",ASSURANCE_E2_16_BYTE_POLICY_FRAME;
  "ASSURANCE_E2_16_BYTE_EXTENDED_ABI",parse_term "!pc stackpointer ra p q m rp xp ordinary s a.\n    bp_e2_crypto_pre pc stackpointer ra p q 16 m rp xp ordinary s\n    ==> eventually_n abi_scalar_extended_step 15\n      (\\t. bp_assurance_16_byte_post pc stackpointer ra p q (read events s) m s\n             (FST t) /\\ SND t = a /\\\n           abi_required_controls_preserved a (SND t)) (s,a)",ASSURANCE_E2_16_BYTE_EXTENDED_ABI;
  "BP_READ_BYTES_AT_ZERO",parse_term "!m p n. read (bytes(p:int64,n)) m =\n          read (bytes(word 0,n)) (\\a. m(word_add p a))",BP_READ_BYTES_AT_ZERO;
