  "BP_PREFIX_16_SPLIT",parse_term "!P:num->bool. (!i. i<16 ==> P i) <=>\n                (!i. i<8 ==> P i) /\\ (!i. i<8 ==> P(8+i))",BP_PREFIX_16_SPLIT;
  "BP_WORDPAIR_BYTE16",parse_term "!m p q.\n   (read (bytes64(p:int64)) m = read (bytes64 q) m /\\\n    read (bytes64(word_add p (word 8))) m =\n    read (bytes64(word_add q (word 8))) m) <=>\n   (!i. i<16 ==> m(word_add p (word i)) = m(word_add q (word i)))",BP_WORDPAIR_BYTE16;
